entries[11048] = { ["name"] = "Dauerhafte 'Bischöfin Tyriona'-Illusion", ["text"] = "Wirken in 3 sek.\nVerkleidet den Zaubernden auf unbestimmte Zeit als Priesterin Tyriona." }
