entries[11113] = { ["name"] = "Druckwelle", ["text"] = "40 Meter Reichweite\nSofort\nEine Flammenwelle geht vom Zielgebiet aus. Alle Gegner, die sich im Einflussbreich befinden, werden 3 Sek. lang um 50% verlangsamt." }
entries[11129] = { ["name"] = "Einäschern", ["text"] = "10% von Grundmana 40 Meter Reichweite\nSofort 45 sek. Abklingzeit\nVerursacht sofort 1 Feuerschaden und betäubt das Ziel 3 Sek. lang.\n\nIst das Ziel bereits mit Eurem 'Entzünden'-Effekt belegt, erleidet das Ziel zusätzlich im Verlauf von 10 Sek. alle 1 Sek. Feuerschaden in Höhe von 50% (20% in PvP) des Tickschadens von 'Entzünden'.\n\nBeim Wirken dieses Zaubers wird die Abklingzeit Eures Zaubers 'Infernoschlag' abgeschlossen." }
entries[11130] = { ["name"] = "Wegschlagen", ["text"] = "10 Meter Reichweite\nSofort\nFügt nahen Gegnern normalen Schaden plus 30 zu und stößt sie zurück." }
