entries[11426] = { ["name"] = "Eisbarriere", ["text"] = "3% von Grundmana\nSofort 25 sek. Abklingzeit\nHüllt Euch sofort in einen Schild, der ( 4580 + Frostzaubermacht * 3.3) Schaden absorbiert. Hält 1 Min. lang an. Während der Schild vorhält, wird Eure Zauberzeit nicht durch erlittenen Schaden beeinträchtigt." }
