entries[11444] = { ["name"] = "Untote fesseln", ["text"] = "50 Mana 30 Meter Reichweite\nWirken in 2 sek.\nFesselt einen untoten Feind bis zu 20 Sek. lang und hindert ihn daran, Zauber zu wirken, anzugreifen oder sich zu bewegen. Jeglicher zugefügte Schaden wird das Ziel befreien. Es kann immer nur jeweils ein Ziel gefesselt sein." }
entries[11445] = { ["name"] = "Knochenrüstung", ["text"] = "10% von Grundmana\nSofort 4 sek. Abklingzeit\nHüllt den Zaubernden in eine Knochenrüstung und absorbiert 1 Min. lang 278 bis 322 Schaden. Solange die Rüstung hält, kann das Wirken von Zaubern nicht durch körperliche Angriffe unterbrochen werden." }
