entries[12292] = { ["name"] = "Blutbad", ["text"] = "Sofort 1 min Abklingzeit\nWährend der nächsten 12 Sek. verursachen Eure Spezialnahkampfangriffe im Verlauf von 6 Sek. zusätzlich 30% Blutungsschaden. Solange das Ziel blutet, ist sein Bewegungstempo um 50% verringert." }
entries[12294] = { ["name"] = "Tödlicher Stoß", ["text"] = "Nahkampfreichweite\nSofort 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nWaffen ( Hotfix - Passivfähigkeit )\nEin heimtückischer Angriff, der 215% Waffenschaden plus 1 verursacht und das Ziel mit dem Effekt 'Trauma' belegt.\n\nErzeugt 10 Wut.\n\nTrauma\nVerwundet das Ziel schwer und verringert so 10 Sek. lang die erhaltene Heilung des Ziels.\n\nEin heimtückischer Angriff, der 175% Waffenschaden plus 1 verursacht und das Ziel mit dem Effekt 'Trauma' belegt.\n\nErzeugt 10 Wut. [ Glyphe 'Tödlicher Stoß' : Wenn ein Ziel mit Eurem Effekt 'Trauma' belegt ist, wird Eure erhaltene Heilung um 10% erhöht ]\nTrauma\nVerwundet das Ziel schwer und verringert so 10 Sek. lang die erhaltene Heilung des Ziels." }
