entries[12880] = { ["name"] = "Wutanfall", ["text"] = "Sofort\nFuror ( Hotfix - Passivfähigkeit )\nKritische Treffer Eurer Fähigkeiten 'Tödlicher Stoß', 'Blutdurst', 'Kolossales Schmettern', 'Verwüsten' und 'Schildschlag' sowie kritisches Blocken versetzen Euch in einen Wutzustand, der 10 Wut erzeugt und Euren körperlichen Schaden 6 Sek. lang um 10% erhöht.\n\nWaffen, Schutz\nKritische Treffer Eurer Fähigkeiten 'Tödlicher Stoß', 'Blutdurst', 'Kolossales Schmettern', 'Verwüsten' und 'Schildschlag' sowie kritisches Blocken versetzen Euch in einen Wutzustand, der 10 Wut erzeugt und Euren körperlichen Schaden 6 Sek. lang um 10% erhöht." }
