entries[13704] = { ["name"] = "Psychischer Schrei", ["text"] = "210 Mana\nSofort\nStößt einen psychischen Schrei aus, der 4 Sek. lang bis zu 5 in der Nähe befindliche Feinde in die Flucht schlägt." }
