entries[13728] = { ["name"] = "Erdschock", ["text"] = "20 Meter Reichweite\nSofort\nSchockt einen Gegner mit erschütternder Kraft, verursacht Naturschaden und unterbricht 2 Sek. lang den gewirkten Zauber." }
entries[13729] = { ["name"] = "Flammenschock", ["text"] = "20 Meter Reichweite\nSofort\nVerbrennt sofort einen Feind und fügt ihm dann 12 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
entries[13730] = { ["name"] = "Demoralisierender Ruf", ["text"] = "Sofort\nVerringert 20 Sek. lang die Nahkampfangriffskraft von Gegnern in der Nähe." }
entries[13735] = { ["name"] = "Erhöhte Beweglichkeit 15", ["text"] = "+15 Beweglichkeit." }
entries[13736] = { ["name"] = "Wirbelwind", ["text"] = "Kanalisiert (Wirken in 2 sek.)\nGreift Gegner in der Nähe in einem Wirbelwind aus Stahl an, der 2 Sek. lang anhält und normalen sowie zusätzlichen Schaden verursacht." }
entries[13737] = { ["name"] = "Tödlicher Stoß", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 130% Waffenschaden und verwundet das Ziel, verringert außerdem die Wirksamkeit jeglicher Heilung 5 Sek. lang um 50%." }
entries[13738] = { ["name"] = "Verwunden", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 15 Sek. lang alle 3 Sek. körperlichen Schaden zu." }
entries[13739] = { ["name"] = "Große Netheressenz", ["text"] = "Sofort\nReagenzien:\nGeringe Netheressenz (3)\nMacht aus drei geringen Netheressenzen eine große Essenz." }
