entries[13744] = { ["name"] = "Loderflammenemblem", ["text"] = "195 Mana 30 Meter Reichweite\nSofort\nErhöht Feuerwiderstand um 50 und verringert jeglichen Feuerschaden 15 Sek. lang um bis zu 213 ." }
entries[13745] = { ["name"] = "Arkane Explosion", ["text"] = "120 Mana\nWirken in 1.5 sek.\nLässt eine Druckwelle aus Magie entstehen und fügt in der Nähe befindlichen Feinden Arkanschaden zu." }
entries[13746] = { ["name"] = "Umhang - Große Verteidigung", ["text"] = "Wirken in 1.5 sek.\nBenötigt Umhang\nTools: Runenverzierte Kupferrute\nReagenzien:\nVisionenstaub (3)\nEinen Umhang dauerhaft verzaubern, sodass die Rüstung um 50 erhöht wird." }
entries[13747] = { ["name"] = "Verlangsamen", ["text"] = "140 Mana 30 Meter Reichweite\nSofort 10 sek. Abklingzeit\nErhöht die Zeit zwischen Angriffen sowie die Zauberzeit von Gegnern in der Nähe um 50% und verlangsamt ihr Bewegungstempo um 60%. Hält 6 Sek. lang an." }
entries[13748] = { ["name"] = "Arkanblitz", ["text"] = "90 Mana 40 Meter Reichweite\nWirken in 1 sek.\nSchleudert einen magischen Blitz auf einen Feind und verursacht Arkanschaden." }
entries[13750] = { ["name"] = "Adrenalinrausch", ["text"] = "Sofort 3 min Abklingzeit\nErhöht 15 Sek. lang Eure Energieregenerationsrate um 100% und Euer Nahkampfangriffstempo um 20%.\nWährend 'Adrenalinrausch' aktiv ist, rufen Eure Fähigkeiten 'Finsterer Stoß', 'Enthüllender Stoß', 'Ausweiden', 'Blutung' und 'Zerhäckseln' eine um 0,2 Sek. verringerte globale Abklingzeit hervor." }
entries[13752] = { ["name"] = "Feenfeuer", ["text"] = "55 Mana 30 Meter Reichweite\nSofort\nVerringert die Rüstung des Ziels 30 Sek. lang um 887 . Während der Wirkungsdauer kann das Ziel weder Verstohlenheit anwenden noch unsichtbar werden." }
entries[13787] = { ["name"] = "Dämonenrüstung", ["text"] = "275 Mana\nSofort 10 sek. Abklingzeit\nSchützt den Zaubernden, erhöht 30 Min. lang Rüstung, Schattenwiderstand und Gesundheitsregeneration." }
entries[13795] = { ["name"] = "Feuerbrandfalle", ["text"] = "Sofort 30 sek. Abklingzeit\nPlatziert eine Feuerfalle, die dem ersten sich nähernden Feind im Verlauf von 15 Sek. insgesamt [(Fernkampfangriffskraft * 0.02 + 638 ) * 5]] Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen." }
