entries[13797] = { ["name"] = "Feuerbrandfalle", ["text"] = "10 Meter Reichweite\nSofort\nPlatziert eine Feuerfalle, die dem ersten sich nähernden Feind im Verlauf von 15 Sek. insgesamt [(Fernkampfangriffskraft * 0.02 + 638 ) * 5]] Feuerschaden zufügt. Die Falle bleibt 1 Min. lang bestehen." }
entries[13808] = { ["name"] = "M73 Schrapnellgranate", ["text"] = "30 Meter Reichweite\nSofort\nFügt Zielen in einem Umkreis von 10 Metern 175 Feuerschaden zu und macht sie 3 Sek. lang handlungsunfähig. Jeglicher Schaden wird den Effekt abbrechen." }
entries[13809] = { ["name"] = "Frostfalle", ["text"] = "Sofort 30 sek. Abklingzeit\nPlatziert eine Eisfalle, die 30 Sek. lang um sich herum eine Eisfläche bildet, sobald sich ihr der erste Gegner nähert. Das Bewegungstempo aller Gegner in einem Umkreis von 10 Metern wird um 50% verringert, solange sie sich im Effektbereich befinden. Die Falle bleibt 1 Min. lang bestehen." }
