entries[13812] = { ["name"] = "Sprengfalle", ["text"] = "Sofort\nPlatziert eine Feuerfalle, die explodiert, wenn sich ein Feind nähert. [ Glyphe 'Sprengfalle' : Dabei werden alle Gegner zurückgestoßen / Die Falle verursacht 125 Feuerschaden und fügt zusätzlich allen Gegnern im Umkreis von 10 Metern im Verlauf von 20 Sek. insgesamt ( 1 * 10) Feuerschaden zu.] Die Falle bleibt 1 Min. lang bestehen." }
